const app=$('app'),gameContent=document.createElement('div');gameContent.id='gameContent';while(app.firstChild)gameContent.appendChild(app.firstChild);gameContent.hidden=true;app.appendChild(gameContent);const prepView=document.createElement('section');prepView.className='prepView';prepView.hidden=true;prepView.innerHTML=`<div class="prepCard"><div class="prepVisual"></div><div class="prepPanel"><div class="prepEyebrow">ICE CREAM BASE · KITCHEN TIME</div><h2>先做一锅冰淇淋原液</h2><p id="prepDescription">从鸡蛋开始，把每一道小工序都完成吧。</p><div class="prepSteps" id="prepSteps"></div><div class="prepMaterials" id="prepMaterials"></div><button class="prepAction" type="button" id="prepAction">轻敲鸡蛋</button><div class="prepMeter"><span id="prepProgress"></span></div><div class="prepMeterLine"><span id="prepProgressLabel">打鸡蛋</span><span id="prepProgressText">0%</span></div><div class="prepHint" id="prepHint">连续点击 3 次，把鸡蛋打进碗里。</div></div></div>`;app.prepend(prepView);
const prepStages=[{name:'打鸡蛋',description:'把鸡蛋轻轻敲进碗里。',hint:'连续点击 3 次，把鸡蛋打进碗里。',action:'轻敲鸡蛋',need:3,items:['🥚 鸡蛋']},{name:'微微搅拌',description:'搅到蛋液微微发白、带一点空气感。',hint:'连续搅拌 5 次，看到细小气泡。',action:'开始搅拌',need:5,items:['🪄 打发器']},{name:'加入原料',description:'依次加入纯牛奶、白砂糖和奶油。',hint:'把台面旁的三种原料都加入。',action:'等待加入',need:3,items:['🥛 纯牛奶','🍚 白砂糖','🥣 奶油'],choose:true},{name:'打发',description:'把混合液打发成柔软、均匀的原液。',hint:'连续打发 5 次，原液会更蓬松。',action:'打发原液',need:5,items:['🪄 打发器']},{name:'小锅熬煮',description:'开小火，用小锅慢慢熬到微微浓稠。',hint:'保持小火，搅动 4 次。',action:'小火熬煮',need:4,items:['🍲 小锅']},{name:'加入口味',description:'选择今天要做的口味，加入对应配料。',hint:'从右侧小碗里挑一种喜欢的口味。',action:'选择配料',need:1,items:['🍓 草莓','🍫 巧克力','🍵 抹茶','🫐 蓝莓','🤍 香草'],flavor:true},{name:'送入冷冻',description:'把原液放进冷冻，等它变成可以挖的一桶冰淇淋。',hint:'连续点击 4 次，完成冷冻。',action:'送入冷冻',need:4,items:['❄️ 冷冻柜']}];
let prepStage=0,prepCount=0,prepUsed=[],introStarted=false,prepFlavor=0;function renderPrep(){const s=prepStages[prepStage],percent=Math.round(prepCount/s.need*100);$('prepDescription').textContent=s.description;$('prepSteps').innerHTML=prepStages.map((x,i)=>`<div class="prepStep ${i<prepStage?'done':i===prepStage?'active':''}">${i+1}. ${x.name}</div>`).join('');$('prepMaterials').innerHTML='';s.items.forEach((item,i)=>{const b=document.createElement('button');b.type='button';b.className='prepItem '+(prepUsed.includes(i)?'used':'available');b.textContent=prepUsed.includes(i)?`✓ ${item}`:item;b.disabled=prepUsed.includes(i);b.onclick=()=>{if(!(s.choose||s.flavor))return;prepUsed.push(i);prepCount=prepUsed.length;if(s.flavor)prepFlavor=i===4?1:i===0?0:i===1?2:i===2?3:4;renderPrep();if(prepCount>=s.need)advancePrep()};$('prepMaterials').append(b)});$('prepAction').textContent=s.action;$('prepAction').disabled=!!(s.choose||s.flavor);$('prepProgress').style.width=`${percent}%`;$('prepProgressLabel').textContent=s.name;$('prepProgressText').textContent=`${percent}%`;$('prepHint').textContent=s.hint}function advancePrep(){if(prepStage<prepStages.length-1){prepStage++;prepCount=0;prepUsed=[];setTimeout(renderPrep,360)}else finishPrep()}$('prepAction').onclick=()=>{const s=prepStages[prepStage];if(s.choose||s.flavor)return;prepCount=Math.min(s.need,prepCount+1);renderPrep();if(prepCount>=s.need)advancePrep()};function finishPrep(){prepView.hidden=true;gameContent.hidden=false;started=true;round=prepFlavor;selected=orderFlavor();updateMusic();playEffect('footsteps');sync();setStatus('冰淇淋做好啦！在冰淇淋表面按住持续拖动，勺里的冰淇淋会慢慢成团。');setTimeout(()=>$('play').scrollIntoView({behavior:'smooth',block:'start'}),180)}
