const sauceDragStyle=document.createElement('style');sauceDragStyle.textContent=`.sauceDrag{position:fixed;z-index:99;pointer-events:none;padding:7px 10px;border-radius:999px;background:#fffaf2eF;border:1px solid #e7cbd8;box-shadow:0 5px 15px #70455d45;color:#754d75;font:800 13px system-ui,"Microsoft YaHei",sans-serif;transform:translate(-50%,-125%) scale(1.08)}.sauceDrag.drop{animation:sauceDrop .28s ease-out both}@keyframes sauceDrop{to{transform:translate(-50%,-42%) scale(.4);opacity:0}}`;document.head.append(sauceDragStyle);let sauceDrag=null;function canvasPoint(clientX,clientY){const r=canvas.getBoundingClientRect();return{x:(clientX-r.left)*900/r.width,y:(clientY-r.top)*600/r.height}}function beginSauceDrag(e,kind){if(!cupBalls.length)return;const protectedBalls=cupBalls.map(ball=>({...ball}));topping=kind;if(!cupBalls.length)cupBalls.push(...protectedBalls);const ghost=document.createElement('div');ghost.className='sauceDrag';ghost.textContent=`✦ ${kind}`;document.body.append(ghost);sauceDrag={kind,ghost};moveSauceDrag(e)}function moveSauceDrag(e){if(!sauceDrag)return;sauceDrag.ghost.style.left=`${e.clientX}px`;sauceDrag.ghost.style.top=`${e.clientY}px`}function endSauceDrag(e){if(!sauceDrag)return;const drag=sauceDrag,rect=canvas.getBoundingClientRect(),insideCanvas=e.clientX>=rect.left&&e.clientX<=rect.right&&e.clientY>=rect.top&&e.clientY<=rect.bottom;if(insideCanvas){const p=canvasPoint(e.clientX,e.clientY),target=[...cupBalls].sort((a,b)=>a.y-b.y).find(b=>Math.hypot(p.x-b.x,p.y-b.y)<b.r*1.18);if(target){target.topping=drag.kind;setStatus(`${drag.kind} 已淋在这颗冰淇淋球上。`);sync()}}drag.ghost.classList.add('drop');setTimeout(()=>drag.ghost.remove(),300);sauceDrag=null}document.addEventListener('pointerdown',e=>{const chip=e.target.closest('#toppings .chip');if(chip)beginSauceDrag(e,chip.textContent.trim())});document.addEventListener('pointermove',moveSauceDrag);document.addEventListener('pointerup',endSauceDrag);
