 if(s.type==='egg'){uSetFrame(uValue===0?'eggEmpty':uValue===1?'eggOne':'eggTwo');uAddToken('eggTray','5%','58%','egg')}
 if(s.type==='stir'){const n=Math.min(2,Math.floor(uValue/s.need*3));uSetFrame(s.frames[n]);uAddToken('whisk','6%','60%','stir')}
 if(s.type==='adds'){const keys=['milk','cream','sugar'],pours=['milkPour','creamPour','sugarPour'];uSetFrame(uValue===0?'base0':pours[Math.min(2,uValue-1)]);if(uValue<3)uAddToken(keys[uValue],'5%','58%','add')}
 if(s.type==='flavor'){if(!uFlavorMix){uSetFrame('heat2');const opts=['straw0','choc0','blue0','matcha0','heat0'];opts.forEach((k,n)=>uAddToken(k,`${3+n*19}%`,'57%','flavor-'+n))}else{const fs=uFlavorKeys(),n=Math.min(2,Math.floor(uValue/s.need*3));uSetFrame(fs[n]);uAddToken('whisk','6%','60%','stir')}}
 if(s.type==='freeze'){uSetFrame(uValue?'freezerClose':'freezerOpen');if(!uValue)uAddToken(uFlavor===1?'choc2':uFlavor===2?'blue2':uFlavor===3?'matcha2':uFlavor===0?'straw2':'heat2','5%','57%','freeze')}
